      да(JSON.stringify(r.дивы) === JSON.stringify(ожид), "на экране столбец 4 по строкам", JSON.stringify(r.дивы));
      да(r.своё === "объекты по Приложению 1", "объекты, записанные словами, печатаются как есть", r.своё);
      await q.evaluate(() => паспортВWord(""));
      const ф = await собратьФайлы(q); const п = ф.find(x => /docx$/.test(x));
