      await подать(q2, () => exchangeImport(), ф1);
      const на2 = await q2.evaluate(() => ({ г: live(ПГ).length, отм: live(ПГО).length,
        день: (найтиПоИд(live(ПГП), "ПГП-ВД-2027-002") || {}).месяцы, карт: live(ВИБК).length }));
      да(на2.г === 4 && на2.отм === 1 && на2.день && на2.день["2027-06"] === "2027-06-14",
        "обмен: новые планы-графики, уточнённый день и отметка доходят на другое место", JSON.stringify(на2));
      await перезагрузить(q);
      да(await q.evaluate(() => live(ПГ).length === 4 && live(ПГО).length === 1), "после перезагрузки всё на месте");
